function initials(name){return formatPersonName(name||'Employee').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
function historyHTML(h){const u=state.users.find(x=>x.id===h.actorUid),avatar=u?.avatarURL;return`<div class="history-item"><span class="history-avatar">${avatar?`<img src="${esc(avatar)}" alt="">`:esc(initials(h.actorName))}</span><strong>${esc(h.toolLabel||'')} ${esc(h.toolName||'')}</strong><div>${esc(h.action||'Updated')}${h.note?` — ${esc(h.note)}`:''}</div><time>${esc(formatPersonName(h.actorName||'Employee'))} · ${formatDate(h.createdAt)}</time></div>`}
function historyType(h){const a=String(h.action||'').toLowerCase(),n=String(h.note||'').toLowerCase();if(a.includes('ownership transfer')||a.includes('transferred to'))return'transfers';if(a.includes('verified'))return'verification';if(a.includes('tool id'))return'ids';if(a.includes('added'))return'added';if(a.includes('condition')||a.includes('status')||a.includes('attention')||a.includes('repair')||a.includes('damag'))return'condition';if(a.includes('moved')||a.includes('location')||a.includes('→')||n.includes('→'))return'moves';return'other'}
function historyDate(h){return h.createdAt?.toDate?h.createdAt.toDate():new Date(h.createdAt||0)}
function historyGroupLabel(d){const now=new Date(),startToday=new Date(now.getFullYear(),now.getMonth(),now.getDate()),startYesterday=new Date(startToday);startYesterday.setDate(startYesterday.getDate()-1);const startWeek=new Date(startToday);startWeek.setDate(startWeek.getDate()-6);if(d>=startToday)return'Today';if(d>=startYesterday)return'Yesterday';if(d>=startWeek)return'This Week';return d.toLocaleDateString([],{month:'long',year:'numeric'})}
function renderHistory(){if(!$('historyList'))return;const q=($('historySearch')?.value||'').trim().toLowerCase(),filter=state.historyFilter||'all';let rows=(isAdmin()?state.history:state.companyHistory).filter(h=>{const type=historyType(h);if(filter!=='all'&&type!==filter)return false;if(!q)return true;return[h.toolLabel,h.toolName,h.action,h.note,h.actorName].some(v=>String(v||'').toLowerCase().includes(q))});if(!rows.length){$('historyList').innerHTML='<div class="panel empty">No matching tool history.</div>';return}const groups=[];for(const h of rows){const label=historyGroupLabel(historyDate(h));let g=groups.find(x=>x.label===label);if(!g){g={label,rows:[]};groups.push(g)}g.rows.push(h)}$('historyList').innerHTML=groups.map(g=>`<section class="history-group"><div class="history-group-title">${esc(g.label)}</div><div class="panel"><div class="panel-body timeline">${g.rows.map(historyHTML).join('')}</div></div></section>`).join('')}

