function filteredTools(){const q=$('searchInput').value.trim().toLowerCase(),status=$('statusFilter').value,loc=$('locationFilter').value,cat=$('categoryFilter').value,power=$('powerFilter')?.value||'';let rows=companyTools().filter(t=>{const hay=[t.label,t.name,t.brand,t.model,t.serial,t.categoryName,t.category,t.locationName,t.powerType].join(' ').toLowerCase();const catMatch=!cat||t.categoryId===cat||(!t.categoryId&&currentCategory(cat)?.name===t.category);const powerMatch=!power||(power==='Not set'?!t.powerType:t.powerType===power);return(!q||hay.includes(q))&&(!status||t.status===status)&&(!loc||t.locationId===loc)&&catMatch&&powerMatch});if(state.toolJobFilter){const ids=new Set(state.locations.filter(l=>l.jobId===state.toolJobFilter).map(l=>l.id));rows=rows.filter(t=>ids.has(t.locationId))}if(state.specialToolFilter==='attention')rows=rows.filter(t=>verificationState(t).needs);if(state.specialToolFilter==='missing')rows=rows.filter(t=>['Missing','Lost'].includes(t.status));return rows}
