async function geocodeAddress(address){
  if(!address)return null;const key='tt-geo-'+address.toLowerCase();try{const cached=JSON.parse(localStorage.getItem(key)||'null');if(cached?.lat&&cached?.lon)return cached}catch{}
  try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=ca&q=${encodeURIComponent(address)}`,{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('geocode');const data=await r.json();if(!data[0])return null;const point={lat:Number(data[0].lat),lon:Number(data[0].lon)};localStorage.setItem(key,JSON.stringify(point));return point}catch(err){console.warn('Map geocoding failed',address,err);return null}
}
async function renderMap(){
  const el=$('liveMap');if(!el||state.currentView!=='mapView'||!window.L)return;const jobs=state.jobs.filter(j=>j.status==='Active'&&j.address);
  if(!state.leafletMap){state.leafletMap=L.map(el,{zoomControl:true}).setView([49.15,-122.9],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(state.leafletMap)}
  setTimeout(()=>state.leafletMap.invalidateSize(),50);state.mapMarkers.forEach(m=>m.remove());state.mapMarkers=[];
  if(!jobs.length){$('mapStatus').textContent='No active jobs with addresses yet.';return}$('mapStatus').textContent='Locating active jobs…';const bounds=[];let found=0;
  for(const j of jobs){const point=await geocodeAddress(j.address);if(!point)continue;const ids=new Set(state.locations.filter(l=>l.jobId===j.id).map(l=>l.id)),tools=companyTools().filter(t=>ids.has(t.locationId)),attention=tools.filter(t=>verificationState(t).needs).length;const popup=`<div class="map-popup"><h3>${esc(j.name)}</h3><p>${esc(j.address)}</p><strong>${tools.length} tool${tools.length===1?'':'s'} · ${attention?`${attention} need attention`:'all current'}</strong><br><a class="btn smallbtn" href="${mapsURL(j.address)}" target="_blank" rel="noopener">Directions</a> <button class="btn accent smallbtn" data-map-job="${j.id}">View inventory</button></div>`;const marker=L.marker([point.lat,point.lon]).addTo(state.leafletMap).bindPopup(popup);state.mapMarkers.push(marker);bounds.push([point.lat,point.lon]);found++}
  if(bounds.length===1)state.leafletMap.setView(bounds[0],13);else if(bounds.length>1)state.leafletMap.fitBounds(bounds,{padding:[35,35]});$('mapStatus').textContent=found===jobs.length?`${found} active jobsite pin${found===1?'':'s'} shown.`:`${found} of ${jobs.length} active job addresses could be located. Check any missing address.`
}

function categoryIconKey(c){const current=c.iconKey||'other',n=String(c.name||'').toLowerCase();const rules=[['pneumatic nail','pneumaticNailer'],['air line','airhose'],['air hose','airhose'],['electrical cord','cord'],['extension cord','cord'],['saw stand','stand'],['stand','stand'],['ladder','ladder'],['scaffold','scaffold'],['harness','safety'],['lifeline','safety'],['safety','safety'],['tool storage','storage'],['jobox','storage'],['compressor','compressor'],['nailer','nailer'],['nail gun','nailer'],['grinder','grinder'],['generator','generator'],['light','lighting'],['vacuum','vacuum'],['laser','laser'],['rotary','concrete'],['concrete','concrete'],['drill','drill'],['saw','saw']];const mapped=rules.find(([word])=>n.includes(word))?.[1];return mapped||current||'other'}
