async function syncToolPairing(toolId,newPairId,oldPairId=''){
  if(!isAdmin())return;
  const tool=state.tools.find(t=>t.id===toolId)||{id:toolId,label:$('toolLabel')?.value||'',name:$('toolName')?.value||'Tool',inventoryScope:'company'};
  if(oldPairId&&oldPairId!==newPairId){
    const old=state.tools.find(t=>t.id===oldPairId);
    if(old?.pairedToolId===toolId)await updateDoc(doc(db,'tools',oldPairId),{pairedToolId:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});
    if(old){await writeHistory(old,`Unpaired from ${tool.label||tool.name}`);await writeHistory(tool,`Unpaired from ${old.label||old.name}`)}
  }
  if(newPairId&&newPairId!==oldPairId){
    const pair=state.tools.find(t=>t.id===newPairId);if(!pair)return;
    if(pair.pairedToolId&&pair.pairedToolId!==toolId)throw new Error(`${pair.label||pair.name} is already paired with another tool.`);
    await updateDoc(doc(db,'tools',newPairId),{pairedToolId:toolId,updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});
    await updateDoc(doc(db,'tools',toolId),{pairedToolId:newPairId,updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});
    await writeHistory(pair,`Paired with ${tool.label||tool.name}`);await writeHistory(tool,`Paired with ${pair.label||pair.name}`);
  }
}
function autoCategoryFromText(text){const s=String(text||'').toLowerCase(),pairs=[['stand','stand'],['vacuum','vacuum'],['dust extractor','vacuum'],['grinder','grinder'],['compressor','compressor'],['nailer','nailer'],['nail gun','nailer'],['rotary hammer','concrete'],['hammer drill','concrete'],['drill','drill'],['driver','drill'],['laser','laser'],['saw','saw'],['generator','generator'],['light','lighting'],['ladder','ladder'],['scaffold','scaffold'],['harness','safety'],['lifeline','safety'],['cord','electrical']];const key=pairs.find(([word])=>s.includes(word))?.[1];if(!key)return;const c=state.categories.find(c=>c.iconKey===key||String(c.name||'').toLowerCase().includes(pairs.find(p=>p[1]===key)?.[0]||''));if(c)$('toolCategory').value=c.id}
async function scanNameplate(){
  const file=$('nameplateFile')?.files?.[0];if(!file)return toast('Take a clear photo of the information/nameplate label first.',true);
  $('nameplateScanStatus').textContent='Reading the information label on this device…';
  try{
    if(!window.Tesseract){const mod=await import('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/+esm');window.Tesseract=mod}
    const scanFile=await compressImage(file,1200,.78);const result=await window.Tesseract.recognize(scanFile,'eng'),text=(result?.data?.text||'').trim(),upper=text.toUpperCase();
    $('nameplateDetectedText').textContent=text||'No text detected.';$('detectedTextDetails')?.classList.remove('hidden');
    if(!text){$('nameplateScanStatus').textContent='No useful label text found. Continue manually.';return toast('No useful nameplate text detected.',true)}
    const suggestions=[];
    const known=[['DEWALT','DeWalt'],['BOSCH','Bosch'],['MILWAUKEE','Milwaukee'],['MAKITA','Makita'],['HILTI','Hilti'],['FESTOOL','Festool'],['RIDGID','Ridgid'],['METABO','Metabo'],['BOSTITCH','Bostitch'],['PASLODE','Paslode'],['STABILA','Stabila'],['EMPIRE','Empire'],['SENCO','Senco']];
    const brand=known.find(([raw])=>upper.includes(raw));if(brand&&!$('toolBrand').value){$('toolBrand').value=brand[1];suggestions.push('Brand')}
    const cleaned=upper.replace(/\bTYPE\s*\d+[A-Z]?\b/g,' ').replace(/\b(?:VOLTS?|AMPS?|HZ|RPM|WARNING|CAUTION)\b/g,' ');
    const explicit=[/(?:MODEL|MOD(?:EL)?\.?|CAT(?:ALOG)?\.?\s*(?:NO\.?)?)\s*[:#-]?\s*([A-Z0-9][A-Z0-9._/-]{2,20})/i];
    let model=explicit.map(p=>cleaned.match(p)).find(Boolean)?.[1]||'';
    if(!model){
      const stop=/^(TYPE|SERIAL|WARNING|CAUTION|CANADA|CHINA|USA|RPM|AMPS?|VOLTS?|HZ|WWW|HTTP|CAT|MODEL)$/;
      const candidates=(cleaned.match(/\b[A-Z]{1,5}[0-9][A-Z0-9-]{2,14}\b/g)||[]).filter(x=>!stop.test(x)&&!/^20\d{2}$/.test(x)&&!/^\d+(?:V|A|HZ|RPM)$/.test(x));
      if(candidates.length)model=candidates.sort((a,b)=>{const score=x=>(/[A-Z]/.test(x)?2:0)+(/[0-9]/.test(x)?2:0)+(x.length>=5&&x.length<=12?2:0)+(brand&&cleaned.indexOf(x)>cleaned.indexOf(brand[0])?1:0);return score(b)-score(a)})[0];
    }
    model=String(model||'').replace(/[-_.:/]*TYPE.*$/i,'').trim().toUpperCase();
    if(model&&!$('toolModel').value){$('toolModel').value=model;suggestions.push('Model')}
    updateLabelSuggestion(false);showDuplicateWarning();
    if(!suggestions.length){$('nameplateScanStatus').textContent='No reliable Brand or Model found. Continue manually.';return toast('No reliable nameplate suggestions found.',true)}
    $('nameplateScanStatus').textContent=`Found ${suggestions.join(', ')}. Review before saving.`;toast(`Nameplate: ${suggestions.join(', ')} suggested.`)
  }catch(err){console.error(err);$('nameplateScanStatus').textContent='Couldn’t read this label reliably. Continue manually.';toast('Nameplate shortcut failed — continue manually.',true)}
}
