function statusForLocation(tool,location){if(!tool||!location)return tool?.status||'Available';if(['Missing','Lost','Retired'].includes(tool.status))return tool.status;const name=String(location.name||'').toLowerCase(),type=String(location.type||'').toLowerCase();if(name.includes('repair')||type.includes('repair'))return 'Repair';if(location.jobId||type==='jobsite')return 'In Use';return 'Available'}
async function saveMove(e){e.preventDefault();const id=$('moveToolId').value,tool=state.tools.find(t=>t.id===id),location=currentLocation($('moveLocation').value);if(!tool||!location)return;const oldStatus=tool.status||'Available',oldLocation=tool.locationName||'Unassigned',requested=$('moveStatus').value,status=requested||statusForLocation(tool,location),note=$('moveNote').value.trim(),locationChanged=(tool.locationId||'')!==location.id,statusChanged=oldStatus!==status;try{const batch=writeBatch(db);batch.update(doc(db,'tools',id),{status,locationId:location.id,locationName:location.name,assignedToUid:status==='In Use'?state.user.uid:'',assignedToName:status==='In Use'?displayName():'',...(status==='Repair'?{needsAttention:true,attentionReason:tool.attentionReason||'Tool moved to Repair'}:{}),updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});const paired=tool.pairedToolId&&state.tools.find(x=>x.id===tool.pairedToolId);const movePair=!!$('movePairedToo')?.checked&&paired&&!['Missing','Lost','Retired'].includes(paired.status);if(movePair)batch.update(doc(db,'tools',paired.id),{locationId:location.id,locationName:location.name,status:statusForLocation(paired,location),updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await batch.commit();if(locationChanged||statusChanged||note){const action=locationChanged?'Location updated':statusChanged?'Status updated':'Tool movement note';const detail=locationChanged?`${oldLocation} → ${location.name}${statusChanged?` · Status ${oldStatus} → ${status}`:''}`:statusChanged?`${oldStatus} → ${status} · ${location.name}`:location.name;await writeHistory(tool,action,`${detail}${note?` · ${note}`:''}`)}if(movePair)await writeHistory(paired,`Moved with paired tool ${tool.label||tool.name} → ${location.name}`,'Paired move');closeModal('moveModal');closeModal('toolDetailModal');toast('Tool updated.')}catch(err){toast(err.message,true)}}

async function reconcileJobLocations(){
  if(!isAdmin())return;
  for(const j of state.jobs){
    if(state.syncingJobLocations.has(j.id))continue;
    const linked=state.locations.find(l=>l.jobId===j.id);
    const shouldActive=j.status!=='Completed';
    const desired={name:j.name||'Jobsite',type:'Jobsite',jobId:j.id,active:shouldActive,updatedAt:serverTimestamp(),updatedBy:state.user.uid};
    try{
      state.syncingJobLocations.add(j.id);
      if(!linked&&shouldActive)await addDoc(collection(db,'locations'),{...desired,createdAt:serverTimestamp()});
      else if(linked&&(linked.name!==desired.name||linked.type!=='Jobsite'||linked.active!==shouldActive))await updateDoc(doc(db,'locations',linked.id),desired);
    }catch(err){console.error('Jobsite location sync failed',j.id,err)}finally{state.syncingJobLocations.delete(j.id)}
  }
}


