async function bulkCloseoutMove(){const jobId=$('closeoutBody')?.dataset.jobId,dest=currentLocation($('closeoutDestination')?.value);const ids=[...document.querySelectorAll('[data-closeout-select]:checked')].map(x=>x.dataset.closeoutSelect);if(!jobId||!dest)return toast('Choose a destination.',true);if(!ids.length)return toast('Select the tools you physically accounted for.',true);const tools=ids.map(id=>state.tools.find(t=>t.id===id)).filter(Boolean);if(tools.some(t=>['Missing','Lost'].includes(t.status)))return toast('Missing tools must be marked Found before moving.',true);try{const batch=writeBatch(db);for(const t of tools)batch.update(doc(db,'tools',t.id),{locationId:dest.id,locationName:dest.name,status:statusForLocation(t,dest),...(statusForLocation(t,dest)==='Repair'?{needsAttention:true,attentionReason:t.attentionReason||'Tool moved to Repair'}:{}),updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await batch.commit();for(const t of tools){const ns=statusForLocation(t,dest);await writeHistory(t,`Location updated`,`${t.locationName||'Unassigned'} → ${dest.name}${(t.status||'Available')!==ns?` · Status ${t.status||'Available'} → ${ns}`:''} · Job Closeout`);}toast(`${tools.length} tool${tools.length===1?'':'s'} moved to ${dest.name}.`);loadCloseout()}catch(err){toast(err.message||'Bulk move failed.',true)}}
