async function applyBulkTransfer(){if(!isAdmin())return;const source=$('transferSource').value,fromPersonal=source==='personal',ids=[...document.querySelectorAll('[data-transfer-select]:checked')].map(x=>x.dataset.transferSelect);if(!ids.length)return toast('Select at least one tool.',true);const dest=fromPersonal?currentLocation($('transferLocation').value):null;if(fromPersonal&&!dest)return toast('Choose the company destination.',true);const updates=[];const labels=new Set((fromPersonal?companyTools():personalTools()).filter(t=>!ids.includes(t.id)).map(t=>String(t.label||'').toLowerCase()));for(const id of ids){const t=state.tools.find(x=>x.id===id),input=document.querySelector(`[data-transfer-label="${CSS.escape(id)}"]`),label=String(input?.value||'').trim();if(!t||!label)return toast('Every selected asset needs a Tool ID.',true);if(labels.has(label.toLowerCase()))return toast(`Tool ID ${label} is already in use.`,true);labels.add(label.toLowerCase());updates.push({t,label})}if(!confirm(`Transfer ${updates.length} asset${updates.length===1?'':'s'} ${fromPersonal?'to Company Inventory':'to Personal Inventory'}? Asset history will not reset.`))return;const btn=$('applyTransferBtn');btn.disabled=true;btn.textContent='Transferring…';try{const batch=writeBatch(db);for(const {t,label} of updates){const old=t.label||'',targetPersonal=!fromPersonal,catSelect=fromPersonal?document.querySelector(`[data-transfer-category="${CSS.escape(t.id)}"]`):null,cat=catSelect?currentCategory(catSelect.value):null;const payload=fromPersonal?{inventoryScope:'company',privateTool:false,label,categoryId:cat?.id||t.categoryId||'',categoryName:cat?.name||t.categoryName||t.category||'',category:cat?.name||t.categoryName||t.category||'',previousLabels:[...(t.previousLabels||[]),...(old&&old!==label?[old]:[])],locationId:dest.id,locationName:dest.name,status:statusForLocation({...t,status:'Available'},dest),assignedToUid:'',assignedToName:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()}:{inventoryScope:'personal',privateTool:true,label,previousLabels:[...(t.previousLabels||[]),...(old&&old!==label?[old]:[])],locationId:'',locationName:'Personal',status:'Owned',assignedToUid:'',assignedToName:'',pairedToolId:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()};batch.update(doc(db,'tools',t.id),payload);if(!fromPersonal&&t.pairedToolId){const pair=state.tools.find(x=>x.id===t.pairedToolId);if(pair?.pairedToolId===t.id){batch.update(doc(db,'tools',pair.id),{pairedToolId:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});const pairHist=doc(collection(db,'history'));batch.set(pairHist,{toolId:pair.id,toolLabel:pair.label||'',toolName:pair.name||'',action:`Unpaired from ${t.label||t.name||'tool'}`,note:'Paired asset moved to Personal Inventory',actorUid:state.user.uid,actorName:displayName(),privateTool:false,createdAt:serverTimestamp()})}}const histRef=doc(collection(db,targetPersonal?'personalHistory':'history'));batch.set(histRef,{toolId:t.id,toolLabel:label,toolName:t.name||'',action:'Ownership transfer',note:`${fromPersonal?'Personal → Company':'Company → Personal'} · ${old||'—'} → ${label}`,actorUid:state.user.uid,actorName:displayName(),privateTool:targetPersonal,createdAt:serverTimestamp()})}await batch.commit();closeModal('transferModal');toast(`${updates.length} asset${updates.length===1?'':'s'} transferred. History preserved.`)}catch(err){console.error(err);toast(err.message||'Transfer failed. No partial transfer was committed.',true)}finally{btn.disabled=false;btn.textContent='Review & transfer'}}
function renderPersonalTools(){if(!$('personalToolsGrid'))return;const rows=personalTools().sort((a,b)=>String(a.label||'').localeCompare(String(b.label||'')));$('personalCount').textContent=`${rows.length} personal tool${rows.length===1?'':'s'}`;$('personalToolsGrid').innerHTML=rows.length?rows.map(t=>{const img=toolImage(t),verify=verificationState(t);return`<article class="tool-card" data-view-tool="${t.id}" tabindex="0">${img?`<img class="tool-thumb" src="${esc(img)}" alt="${esc(t.name)}">`:`<div class="tool-placeholder">${icon('personal')}</div>`}<div class="tool-content"><div class="tool-title"><h3>${esc(t.name||'Unnamed tool')}</h3><span class="label">${esc(t.label||'—')}</span></div><div class="card-actions"><span class="badge">Personal</span>${t.needsAttention?`<span class="badge repair">Needs Attention</span>`:''}${verify.needs?`<button class="badge verify-due verify-action" data-verify-tool="${t.id}">${esc(verify.label)}</button>`:'<span class="badge verified">Verified</span>'}</div><div class="meta"><span>${esc(t.brand||'')} ${esc(t.model||'')}</span><span>${t.purchasePrice!==''&&t.purchasePrice!==undefined?`Paid $${Number(t.purchasePrice).toFixed(2)}`:'Price not entered'}${t.retailer?` · ${esc(t.retailer)}`:''}</span><span>${t.receiptURL?'Receipt attached':'No receipt attached'}</span></div><div class="card-actions"><button class="btn smallbtn" data-view-tool="${t.id}">Details</button><button class="btn smallbtn" data-edit-tool="${t.id}">Edit</button></div></div></article>`}).join(''):'<div class="panel empty" style="grid-column:1/-1">No personal tools yet. Add the first one without affecting company numbering.</div>'}
function openVerify(id){setSaveProgress('verifySaveStatus','');const t=state.tools.find(x=>x.id===id);if(!t)return;$('verifyToolId').value=id;$('verifyStatus').value=t.status==='Lost'?'Missing':(t.status||((t.privateTool||t.inventoryScope==='personal')?'Owned':'Available'));$('verifyCondition').value=t.condition||'Good';$('verifyNote').value='';$('verifyPhoto').value='';if($('verifySeen'))$('verifySeen').checked=false;const personal=t.privateTool||t.inventoryScope==='personal';$('verifyLocationField').classList.toggle('hidden',personal);if(!personal)$('verifyLocation').value=t.locationId||'';openModal('verifyModal')}
async function saveVerify(e){
  e.preventDefault();const btn=$('verifySaveBtn')||e.submitter;if(btn?.disabled)return;if(!$('verifySeen')?.checked)return toast('Physical confirmation is required.',true);const photo=$('verifyPhoto').files?.[0];if(!photo)return toast('Take a fresh condition photo before verification.',true);const id=$('verifyToolId').value,t=state.tools.find(x=>x.id===id);if(!t)return;const personal=t.privateTool||t.inventoryScope==='personal',loc=personal?null:currentLocation($('verifyLocation').value),today=new Date().toISOString().slice(0,10),condition=$('verifyCondition').value,payload={lastVerified:today,condition,status:$('verifyStatus').value,updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()};if(!personal&&loc){payload.locationId=loc.id;payload.locationName=loc.name}if(conditionNeedsAttention(condition)){payload.needsAttention=true;payload.attentionReason=t.attentionReason||`Condition reported during verification: ${condition}`;payload.attentionReportedBy=state.user.uid;payload.attentionReportedByName=displayName();payload.attentionReportedAt=new Date().toISOString();payload.attentionDeferredUntil=''}
  if(btn){btn.disabled=true;btn.classList.add('busy')}setSaveProgress('verifySaveStatus','Preparing photo…');try{setSaveProgress('verifySaveStatus','Uploading photo…');const f=await uploadFileForTool(id,photo,'verify',personal);payload.previousConditionPhotoURL=t.photoURL||'';payload.photoURL=f.url;payload.photoPath=f.path;payload.conditionPhotoAt=today;setSaveProgress('verifySaveStatus','Saving verification…');const batch=writeBatch(db);batch.update(doc(db,'tools',id),payload);if(!personal){const vr=doc(collection(db,'verificationPhotos'));batch.set(vr,{assetId:id,toolLabel:t.label||'',toolName:t.name||'',type:'verification',photoURL:f.url,photoPath:f.path,condition:payload.condition,status:payload.status,locationId:payload.locationId||t.locationId||'',locationName:payload.locationName||t.locationName||'',verifiedDate:today,note:$('verifyNote').value.trim(),actorUid:state.user.uid,actorName:displayName(),createdAt:serverTimestamp()})}await batch.commit();await writeHistory({...t,...payload},'Verified',$('verifyNote').value.trim()||`Confirmed ${personal?'personal ownership':payload.locationName||t.locationName||'location'}`);if(conditionNeedsAttention(condition))await writeHistory({...t,...payload},`Condition reported — ${condition}`,'Raised Needs Attention during physical verification.');closeModal('verifyModal');closeModal('toolDetailModal');toast('Verification saved.')}catch(err){console.error(err);setSaveProgress('verifySaveStatus','Verification failed. Photo/record was not marked complete.');toast(err.message||'Verification failed.',true)}finally{if(btn){btn.disabled=false;btn.classList.remove('busy')}if(!$('verifyModal')?.classList.contains('hidden'))setTimeout(()=>setSaveProgress('verifySaveStatus',''),2500)}}
const QUICK_FIELDS={location:'Location',status:'Status',condition:'Condition',notes:'Notes',model:'Model number',serial:'Serial number',label:'Tool label / ID',purchaseDate:'Purchase date',purchasePrice:'Purchase price',retailer:'Retailer',warrantyExpiry:'Warranty expiry'};
function openQuickEdit(id,field){const t=state.tools.find(x=>x.id===id);if(!t)return;const staffAllowed=['location','status','condition','notes','model','serial'].includes(field);if(!isAdmin()&&!staffAllowed)return toast('Admin controls this field.',true);$('quickEditToolId').value=id;$('quickEditField').value=field;$('quickEditTitle').textContent=`Edit ${QUICK_FIELDS[field]||field}`;const c=$('quickEditControl');if(field==='condition'){c.innerHTML='<label>Condition</label><select id="quickEditValue"><option>New</option><option>Good</option><option>Fair</option><option>Missing Parts</option><option>Needs Service</option><option>Damaged</option></select><label class="condition-photo-label hidden" id="quickConditionPhotoLabel">Fresh condition photo (required)<input id="quickConditionPhoto" type="file" accept="image/*" capture="environment"></label>';c.querySelector('select').value=t.condition||'Good';const toggle=()=>$('quickConditionPhotoLabel')?.classList.toggle('hidden',!conditionNeedsAttention(c.querySelector('select').value));c.querySelector('select').addEventListener('change',toggle);toggle()}else if(field==='location'){c.innerHTML=`<label>Location</label><select id="quickEditValue">${$('toolLocation').innerHTML}</select>`;c.querySelector('select').value=t.locationId||''}else if(field==='status'){c.innerHTML='<label>Status</label><select id="quickEditValue"><option>Available</option><option>In Use</option><option>Repair</option><option>Lost</option><option>Retired</option><option>Owned</option></select>';c.querySelector('select').value=t.status||'Available'}else if(field==='notes'){c.innerHTML='<label>Notes / condition</label><textarea id="quickEditValue" maxlength="1200"></textarea>';c.querySelector('textarea').value=t.notes||''}else{const type=['purchaseDate','warrantyExpiry'].includes(field)?'date':field==='purchasePrice'?'number':'text';c.innerHTML=`<label>${esc(QUICK_FIELDS[field]||field)}</label><input id="quickEditValue" type="${type}" ${field==='purchasePrice'?'step="0.01" min="0"':''}>`;c.querySelector('input').value=t[field]??'';if(field==='label'){const hint=document.createElement('div');hint.id='quickLabelSuggestion';hint.className='suggest hidden';c.appendChild(hint);c.querySelector('input').addEventListener('input',()=>{const scope=(t.privateTool||t.inventoryScope==='personal')?'personal':'company',s=nextToolLabel(t.brand||'',scope,t.id);hint.innerHTML=s?`Suggested next label: <strong>${esc(s)}</strong> <button type="button" class="btn smallbtn" id="quickUseLabel">Use it</button>`:'';hint.classList.toggle('hidden',!s);hint.querySelector('#quickUseLabel')?.addEventListener('click',()=>{c.querySelector('input').value=s})})}}openModal('quickEditModal')}
async function saveQuickEdit(e){e.preventDefault();const id=$('quickEditToolId').value,field=$('quickEditField').value,t=state.tools.find(x=>x.id===id),control=$('quickEditControl').querySelector('#quickEditValue');if(!t||!control)return;let value=control.value;if(['model','serial','label'].includes(field))value=value.trim().toUpperCase();let payload={[field]:field==='purchasePrice'&&value?Number(value):value,updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()};let photoData=null;
  if(field==='condition'&&conditionNeedsAttention(value)){const photo=$('quickConditionPhoto')?.files?.[0];if(!photo)return toast(`A fresh photo is required when reporting ${value}.`,true);photoData=await uploadFileForTool(id,photo,'condition',!!(t.privateTool||t.inventoryScope==='personal'));payload={...payload,needsAttention:true,attentionReason:t.attentionReason||`Condition reported: ${value}`,attentionReportedBy:state.user.uid,attentionReportedByName:displayName(),attentionReportedAt:new Date().toISOString(),attentionDeferredUntil:'',photoURL:photoData.url,photoPath:photoData.path,conditionPhotoAt:new Date().toISOString().slice(0,10)}}
  if(field==='location'){const loc=currentLocation(value);if(!loc)return;payload={locationId:loc.id,locationName:loc.name,status:statusForLocation(t,loc),updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()}}
  try{await updateDoc(doc(db,'tools',id),payload);const saved={...t,...payload};if(photoData)await writeConditionPhotoRecord(saved,photoData,value,'Quick condition report','condition-report');await writeHistory(saved,field==='condition'&&conditionNeedsAttention(value)?`Condition reported — ${value}`:`${QUICK_FIELDS[field]||field} updated`,photoData?'Fresh condition photo captured; Needs Attention opened.':'');closeModal('quickEditModal');closeModal('toolDetailModal');toast('Change saved.')}catch(err){toast(err.message,true)}}
async function readReceipt(){const file=$('receiptFile').files?.[0];if(!file)return toast('Choose a receipt image first.',true);if(file.type==='application/pdf')return toast('PDF will be stored, but receipt reading currently works with photos/images. You can still enter the fields manually.',true);$('receiptScanStatus').textContent='Reading receipt on this device… first scan can take a moment.';try{if(!window.Tesseract){const mod=await import('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/+esm');window.Tesseract=mod}const result=await window.Tesseract.recognize(file,'eng');const text=result?.data?.text||'';const lines=text.split(/\n/).map(x=>x.trim()).filter(Boolean);if(!$('retailer').value&&lines[0])$('retailer').value=lines[0].slice(0,120);const date=text.match(/\b(20\d{2})[-\/.](\d{1,2})[-\/.](\d{1,2})\b/)||text.match(/\b(\d{1,2})[-\/.](\d{1,2})[-\/.](20\d{2})\b/);if(date&&!$('purchaseDate').value){let y,m,d;if(date[1].length===4)[y,m,d]=date.slice(1,4);else [m,d,y]=date.slice(1,4);$('purchaseDate').value=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}const totals=[...text.matchAll(/(?:total|amount)[^\d$]{0,20}\$?\s*(\d{1,5}[.,]\d{2})/ig)].map(m=>Number(m[1].replace(',','.'))).filter(Number.isFinite);if(totals.length&&!$('purchasePrice').value)$('purchasePrice').value=Math.max(...totals).toFixed(2);$('receiptScanStatus').textContent='Receipt read. Suggested values are filled where possible — review and edit before saving.';toast('Receipt suggestions ready.')}catch(err){console.error(err);$('receiptScanStatus').textContent='Could not read this receipt automatically. Keep it attached and fill the fields manually.';toast('Receipt reading failed; the file can still be saved.',true)}}
async function createStaff(e){e.preventDefault();if(!isAdmin())return;const name=$('staffName').value.trim(),email=$('staffEmail').value.trim().toLowerCase(),password=$('staffTempPassword').value;if(!name||!email||password.length<8)return toast('Enter name, email and an 8+ character temporary password.',true);let secondary;try{secondary=initializeApp(firebaseConfig,`staff-${Date.now()}`);const sa=getAuth(secondary),cred=await createUserWithEmailAndPassword(sa,email,password);await setDoc(doc(db,'users',cred.user.uid),{email,displayName:name,role:'staff',active:true,createdAt:serverTimestamp(),createdBy:state.user.uid,updatedAt:serverTimestamp()});await signOut(sa);$('staffCreateForm').reset();toast(`${name}'s crew sign-in is ready.`)}catch(err){console.error(err);toast(err.code==='auth/email-already-in-use'?'That email already has a Firebase sign-in.':err.message,true)}finally{if(secondary)deleteApp(secondary).catch(()=>{})}}


