function pacificWeekKey(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const o=Object.fromEntries(parts.map(x=>[x.type,x.value]));let d=new Date(`${o.year}-${o.month}-${o.day}T12:00:00`);const dow=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(o.weekday);let back=(dow+6)%7;if(dow===1&&(Number(o.hour)<4||(Number(o.hour)===4&&Number(o.minute)<30)))back=7;d.setDate(d.getDate()-back);return d.toISOString().slice(0,10)}
function seededNumber(key,salt=''){let h=2166136261;for(const c of key+salt)h=Math.imul(h^c.charCodeAt(0),16777619);return Math.abs(h%1400)+7}
function setPuzzleLocked(locked){['puzzleHint','puzzleSubmit','puzzleReveal','puzzleAnswer'].forEach(id=>{if($(id))$(id).disabled=locked});$('puzzleAnswer')?.classList.toggle('completed',locked)}
function renderMorale(){const key=pacificWeekKey(),n=seededNumber(key);setPuzzleLocked(localStorage.getItem(`tt-morale-puzzle-${key}`)==='solved');if($('moraleJoke'))$('moraleJoke').textContent=MORALE_JOKES[n%MORALE_JOKES.length];if($('bulletinNo'))$('bulletinNo').textContent=`#${seededNumber(key,'b')}`;if($('incidentNo'))$('incidentNo').textContent=`#${seededNumber(key,'i')}-B`;if($('moraleBulletin'))$('moraleBulletin').textContent='Management would like to remind everyone that putting a tool “somewhere safe” is not an acceptable location in Tool Tracker. Previous attempts to locate Somewhere Safe have been unsuccessful.'}
function renderMasterPhotos(){if(!isAdmin()||!$('masterPhotosGrid'))return;const mode=$('photoMode')?.value||'Current Tool Photos',q=($('photoSearch')?.value||'').toLowerCase();if($('missingPhotoOnly'))$('missingPhotoOnly').closest('label').classList.toggle('hidden',mode!=='Current Tool Photos');let rows=companyTools().filter(t=>t.status!=='Retired').filter(t=>!q||[t.label,t.name,t.brand,t.categoryName].join(' ').toLowerCase().includes(q));if(mode==='Receipts & Documents'){rows=rows.filter(t=>t.receiptURL);$('masterPhotosGrid').innerHTML=rows.length?rows.map(t=>`<a class="master-photo document-card" href="${esc(t.receiptURL)}" target="_blank" rel="noopener"><div class="document-icon">${icon('folder')}</div><strong>${esc(t.label||'—')} · ${esc(t.name||'Tool')}</strong><span>${esc(t.receiptName||'Receipt / document')}</span></a>`).join(''):'<div class="panel empty" style="grid-column:1/-1"><strong>No receipts or documents yet.</strong><br><span class="small muted">Upload receipts, warranty or service records from the relevant tool. This area is Admin-only.</span></div>';return}const missing=$('missingPhotoOnly')?.checked;rows=rows.filter(t=>!missing||!t.photoURL);$('masterPhotosGrid').innerHTML=rows.length?rows.map(t=>{const hist=state.verificationPhotos.filter(v=>v.assetId===t.id);return`<button class="master-photo" data-photo-history="${t.id}">${t.photoURL?`<img src="${esc(t.photoURL)}" alt="${esc(t.name)}" loading="lazy">`:`<div class="photo-missing">No current photo</div>`}<strong>${esc(t.label||'—')} · ${esc(t.name||'Tool')}</strong><span>Current photo · ${hist.length} visual history record${hist.length===1?'':'s'} ›</span></button>`}).join(''):'<div class="panel empty">No photos match this view.</div>'}
function showPhotoHistory(id){const t=state.tools.find(x=>x.id===id);if(!t)return;const rows=state.verificationPhotos.filter(v=>v.assetId===id);$('photoHistoryTitle').textContent=`${t.label||'—'} · ${t.name||'Tool'}`;$('photoHistoryBody').innerHTML=rows.length?rows.map(v=>`<article class="photo-history-entry"><img src="${esc(v.photoURL)}" alt="Condition documentation"><div><strong>${esc(v.type==='condition-report'?'Condition report':'Verification')} · ${esc(v.verifiedDate||v.reportedDate||'')}</strong><span>${esc(v.condition||'')} · ${esc(v.status||'')} · ${esc(v.locationName||'Unassigned')}</span><span>${esc(v.actorName||'Employee')}${v.note?` · ${esc(v.note)}`:''}</span></div></article>`).join(''):'<div class="empty">No visual condition history yet. Verification and damage/condition reports will appear here without changing the asset identity.</div>';openModal('photoHistoryModal')}
function renderInsurance(){if(!isAdmin()||!$('insuranceList'))return;const all=companyTools().filter(t=>t.status!=='Retired'&&t.insuranceIncluded!==false);const verified=all.filter(t=>Number(t.replacementCost)>0);const total=verified.reduce((a,t)=>a+Number(t.replacementCost||0),0),missingSerial=all.filter(t=>!t.serial).length,missingPhoto=all.filter(t=>!t.photoURL).length,completeFields=all.reduce((n,t)=>n+[t.serial,t.photoURL,t.replacementCost].filter(Boolean).length,0),pct=all.length?Math.round(completeFields/(all.length*3)*100):100;$('insuredCount').textContent=all.length;$('replacementTotal').textContent=total.toLocaleString('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0});$('missingSerialCount').textContent=missingSerial;$('missingEvidenceCount').textContent=missingPhoto;$('insuranceCompleteness').textContent=`${pct}% complete`;const q=($('insuranceSearch')?.value||'').toLowerCase(),filter=$('insuranceFilter')?.value||'';let rows=all.filter(t=>!q||[t.label,t.name,t.brand,t.model,t.serial].join(' ').toLowerCase().includes(q)).filter(t=>filter==='needs'?!Number(t.replacementCost):filter==='complete'?(Number(t.replacementCost)>0&&!!t.serial&&!!t.photoURL):filter==='serial'?!t.serial:filter==='photo'?!t.photoURL:filter==='review'?!!t.replacementCostReviewedAt&&daysSince(t.replacementCostReviewedAt)>365:true);const shown=rows.slice(0,state.insuranceLimit);$('insuranceList').innerHTML=shown.map(t=>`<div class="insurance-row"><div><strong>${esc(t.label||'—')} · ${esc(t.name||'Tool')}</strong><small>${esc(t.brand||'')} ${esc(t.model||'')} · ${t.serial?`Serial ${esc(t.serial)}`:'Serial number not recorded'}</small></div><label>Replacement cost <input class="replacement-input" data-replacement-tool="${t.id}" type="number" min="0" step="0.01" value="${Number(t.replacementCost||0)||''}" placeholder="Needs review"></label><span class="badge">${t.replacementCost?'Verified/recorded':'Needs valuation'}</span></div>`).join('')||'<div class="empty">No matching active company assets.</div>';const more=$('insuranceLoadMore');if(more){more.classList.toggle('hidden',rows.length<=state.insuranceLimit);more.textContent=`Load more (${Math.min(25,rows.length-state.insuranceLimit)} more)`}}
async function saveReplacement(id,value){if(!isAdmin())return;await updateDoc(doc(db,'tools',id),{replacementCost:Number(value)||'',replacementCostReviewedAt:new Date().toISOString().slice(0,10),replacementCostBasis:'manual/admin',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});const t=state.tools.find(x=>x.id===id);await writeHistory(t,'Replacement cost reviewed',value?`Current replacement cost: $${Number(value).toFixed(2)}`:'Replacement value cleared');toast('Replacement value saved.')}
function captureRenumberPending(){document.querySelectorAll('[data-renumber-id]').forEach(i=>{const v=i.value.trim(),old=i.dataset.oldLabel.trim();if(v!==old)state.renumberPending.set(i.dataset.renumberId,{old,next:v});else state.renumberPending.delete(i.dataset.renumberId)})}
function renderRenumber(){if(!isAdmin()||!$('renumberList'))return;captureRenumberPending();const q=($('renumberSearch')?.value||'').toLowerCase();const rows=companyTools().filter(t=>t.status!=='Retired').filter(t=>!q||[t.label,t.name,t.brand].join(' ').toLowerCase().includes(q));const shown=rows.slice(0,state.renumberLimit);$('renumberList').innerHTML=`<div class="dataset-count">Showing ${shown.length} of ${rows.length}</div>`+shown.map(t=>{const pending=state.renumberPending.get(t.id);return`<div class="renumber-row"><span><strong>${esc(t.label||'—')}</strong><small>${esc(t.name||'Tool')} · ${esc(t.brand||'')}</small></span><input data-renumber-id="${t.id}" data-old-label="${esc(t.label||'')}" value="${esc(pending?.next??t.label??'')}" aria-label="New Tool ID"></div>`}).join('');const more=$('renumberLoadMore');if(more){more.classList.toggle('hidden',rows.length<=state.renumberLimit);more.textContent=`Load more (${Math.min(25,rows.length-state.renumberLimit)} more)`}}
async function applyRenumber(){if(!isAdmin())return;captureRenumberPending();const changes=[...state.renumberPending.entries()].map(([id,v])=>({id,old:v.old,next:v.next})).filter(x=>x.next&&x.next!==x.old);if(!changes.length)return toast('No Tool ID changes to apply.');const finals=new Map(companyTools().map(t=>[t.id,t.label]));changes.forEach(c=>finals.set(c.id,c.next));const labels=[...finals.values()].map(x=>String(x).toLowerCase());if(new Set(labels).size!==labels.length)return toast('Two tools would end up with the same Tool ID.',true);if(!confirm(`Apply ${changes.length} Tool ID change${changes.length===1?'':'s'}? History will preserve every old → new label.`))return;const batch=writeBatch(db);for(const c of changes)batch.update(doc(db,'tools',c.id),{label:c.next,previousLabels:[...(state.tools.find(t=>t.id===c.id)?.previousLabels||[]),c.old],updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await batch.commit();for(const c of changes){const t=state.tools.find(x=>x.id===c.id);await writeHistory({...t,label:c.next},'Tool ID changed by Admin',`${c.old} → ${c.next}`)}state.renumberPending.clear();toast(`${changes.length} Tool ID${changes.length===1?'':'s'} updated.`)}
async function markAttention(id){const t=state.tools.find(x=>x.id===id);if(!t)return;const reason=prompt('What needs attention?');if(!reason)return;await updateDoc(doc(db,'tools',id),{needsAttention:true,attentionReason:reason,attentionReportedBy:state.user.uid,attentionReportedByName:displayName(),attentionReportedAt:new Date().toISOString(),attentionDeferredUntil:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await writeHistory(t,'Needs Attention reported',reason);toast('Admin has been flagged.')}
async function adminAttention(id,action){if(!isAdmin())return;const t=state.tools.find(x=>x.id===id);if(!t)return;if(action==='resolve'){const note=prompt('Resolution note (optional):')||'';await updateDoc(doc(db,'tools',id),{needsAttention:false,attentionReason:'',attentionDeferredUntil:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await writeHistory(t,'Needs Attention resolved',note);toast('Attention item resolved.')}else{const date=prompt('Defer until (YYYY-MM-DD):',new Date(Date.now()+90*86400000).toISOString().slice(0,10));if(!date)return;const note=prompt('Reason (optional):','Service during slower season')||'';await updateDoc(doc(db,'tools',id),{needsAttention:true,attentionDeferredUntil:date,attentionDeferredReason:note,updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await writeHistory(t,'Needs Attention deferred',`${date}${note?' · '+note:''}`);toast(`Deferred until ${date}.`)}}
function exportInsuranceCSV(){if(!isAdmin())return;const rows=companyTools().filter(t=>t.status!=='Retired'&&t.insuranceIncluded!==false),cols=['Tool ID','Tool','Brand','Model','Serial','Category','Location','Purchase Date','Purchase Price','Current Replacement Cost','Last Verified'];const csv=[cols,...rows.map(t=>[t.label,t.name,t.brand,t.model,t.serial,t.categoryName||t.category,t.locationName,t.purchaseDate,t.purchasePrice,t.replacementCost,t.lastVerified])].map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`Tool-Tracker-Insurance-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}

function csvDownload(name,cols,rows){const csv=[cols,...rows].map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`Tool-Tracker-${name}-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function reportDataset(kind){const tools=companyTools();if(kind==='inventory')return{title:'Tool Inventory',cols:['Tool ID','Tool','Brand','Model','Serial','Category','Condition','Status','Location'],rows:tools.map(t=>[t.label,t.name,t.brand,t.model,t.serial,t.categoryName||t.category,t.condition,t.status,t.locationName])};if(kind==='insurance')return{title:'Insurance',cols:['Tool ID','Tool','Serial','Purchase Price','Replacement Cost','Current Photo','Last Verified'],rows:tools.filter(t=>t.status!=='Retired'&&t.insuranceIncluded!==false).map(t=>[t.label,t.name,t.serial,t.purchasePrice,t.replacementCost,t.photoURL?'Yes':'No',t.lastVerified])};if(kind==='repair')return{title:'Repair & Damage',cols:['Tool ID','Tool','Condition','Status','Needs Attention','Reason','Location'],rows:tools.filter(t=>t.condition==='Damaged'||t.condition==='Needs Service'||t.condition==='Missing Parts'||t.status==='Repair'||t.needsAttention).map(t=>[t.label,t.name,t.condition,t.status,t.needsAttention?'Yes':'No',t.attentionReason,t.locationName])};if(kind==='location')return{title:'Location / Job Inventory',cols:['Location','Tool ID','Tool','Status','Condition'],rows:[...tools].sort((a,b)=>String(a.locationName||'').localeCompare(String(b.locationName||''))).map(t=>[t.locationName,t.label,t.name,t.status,t.condition])};if(kind==='verification')return{title:'Verification',cols:['Tool ID','Tool','Last Verified','Verification State','Condition','Status','Location'],rows:tools.map(t=>{const v=verificationState(t);return[t.label,t.name,t.lastVerified,v.needs?v.label:'Verified',t.condition,t.status,t.locationName]})};return{title:'Tool History',cols:['Date','Tool ID','Tool','Action','Note','User'],rows:(isAdmin()?state.history:state.companyHistory).map(h=>[formatDate(h.createdAt),h.toolLabel,h.toolName,h.action,h.note,h.actorName])}}
function renderReports(){if(!isAdmin()||!$('reportBody'))return;if(!state.activeReport){$('reportBody').innerHTML='<div class="empty">Choose a report above to preview it here.</div>';$('reportControls')?.classList.add('hidden');$('reportLoadMore')?.classList.add('hidden');return}const d=reportDataset(state.activeReport),q=($('reportSearch')?.value||'').toLowerCase();const rows=d.rows.filter(r=>!q||r.join(' ').toLowerCase().includes(q));$('reportTitle').textContent=d.title;$('exportReportBtn').classList.remove('hidden');$('reportControls')?.classList.remove('hidden');const shown=rows.slice(0,state.reportLimit);$('reportBody').innerHTML=`<div class="report-preview"><strong>Showing ${shown.length} of ${rows.length} record${rows.length===1?'':'s'}</strong><div class="report-table-wrap"><table class="report-table"><thead><tr>${d.cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${shown.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">In-app preview is batched for readability. Export CSV includes the full report.</p></div>`;const more=$('reportLoadMore');if(more){more.classList.toggle('hidden',rows.length<=state.reportLimit);more.textContent=`Load more (${Math.min(25,rows.length-state.reportLimit)} more)`}}
function chooseReport(kind){if(!isAdmin())return;state.activeReport=kind;state.reportLimit=25;if($('reportSearch'))$('reportSearch').value='';document.querySelectorAll('[data-report]').forEach(b=>b.classList.toggle('active',b.dataset.report===kind));renderReports()}
function exportActiveReport(){if(!state.activeReport)return;const d=reportDataset(state.activeReport),q=($('reportSearch')?.value||'').toLowerCase(),rows=d.rows.filter(r=>!q||r.join(' ').toLowerCase().includes(q));csvDownload(d.title.replace(/[^a-z0-9]+/gi,'-'),d.cols,rows)}

function v4Refresh(){renderMorale();renderMasterPhotos();renderInsurance();renderRenumber();renderReports()}

