document.addEventListener('click',e=>{
  const button=e.target.closest('button,[data-open-view],[data-view-tool],[data-move-tool],[data-edit-tool],[data-edit-job],[data-job-tools],[data-edit-location],[data-edit-category],[data-edit-wish],[data-category-up],[data-category-down],[data-remove-prefix],[data-preview-image],[data-closeout-move],[data-finish-closeout],[data-verify-tool],[data-quick-edit],[data-map-job],[data-mark-attention],[data-attention-action],[data-found-tool],[data-view-category],[data-browse-category],[data-view-power],[data-view-location],[data-history-filter],[data-report],[data-photo-history],[data-insurance-filter],[data-pair-tool],[data-unpair-tool],[data-transfer-one]');if(!button)return;
  if(button.dataset.close)return closeModal(button.dataset.close);
  if(button.dataset.openView){if(button.dataset.toolFilter){state.specialToolFilter=button.dataset.toolFilter;state.toolJobFilter=null;renderTools()}return openView(button.dataset.openView)}
  if(button.dataset.viewPower){$('categoryFilter').value='';$('locationFilter').value='';if($('powerFilter'))$('powerFilter').value=button.dataset.viewPower;state.toolJobFilter=null;state.specialToolFilter=null;renderTools();return openView('toolsView')}
  if(button.dataset.browseCategory){$('categoryFilter').value=button.dataset.browseCategory;renderTools();return}if(button.dataset.viewCategory){$('categoryFilter').value=button.dataset.viewCategory;$('locationFilter').value='';if($('powerFilter'))$('powerFilter').value='';state.toolJobFilter=null;state.specialToolFilter=null;renderTools();return openView('toolsView')}
  if(button.dataset.viewLocation){$('locationFilter').value=button.dataset.viewLocation;$('categoryFilter').value='';state.toolJobFilter=null;state.specialToolFilter=null;renderTools();return openView('toolsView')}
  if(button.dataset.historyFilter){state.historyFilter=button.dataset.historyFilter;document.querySelectorAll('[data-history-filter]').forEach(b=>b.classList.toggle('active',b.dataset.historyFilter===state.historyFilter));return renderHistory()}
  if(button.dataset.report)return chooseReport(button.dataset.report);
  if(button.dataset.mapJob)return showJobTools(button.dataset.mapJob);if(button.dataset.markAttention)return markAttention(button.dataset.markAttention);if(button.dataset.attentionAction)return adminAttention(button.dataset.toolId,button.dataset.attentionAction);
  if(button.dataset.foundTool)return markFound(button.dataset.foundTool);if(button.dataset.verifyTool)return openVerify(button.dataset.verifyTool);
  if(button.dataset.quickEdit)return openQuickEdit(button.dataset.toolId,button.dataset.quickEdit);
  if(button.dataset.closeoutMove){closeModal('closeoutModal');return moveTool(button.dataset.closeoutMove)}
  if(button.dataset.photoHistory)return showPhotoHistory(button.dataset.photoHistory);if(button.dataset.pairTool)return openPairing(button.dataset.pairTool);if(button.dataset.unpairTool){const t=state.tools.find(x=>x.id===button.dataset.unpairTool);if(t?.pairedToolId&&confirm('Unpair these assets?'))syncToolPairing(t.id,'',t.pairedToolId).then(()=>{closeModal('toolDetailModal');toast('Assets unpaired.')}).catch(err=>toast(err.message,true));return}if(button.dataset.transferOne){const t=state.tools.find(x=>x.id===button.dataset.transferOne);if(!t)return;openBulkTransfer((t.privateTool||t.inventoryScope==='personal')?'personal':'company');setTimeout(()=>{const box=document.querySelector(`[data-transfer-select="${CSS.escape(t.id)}"]`);if(box){box.checked=true;updateTransferSummary();box.scrollIntoView({block:'center'})}},0);return}
  if(button.dataset.insuranceFilter!==undefined){$('insuranceFilter').value=button.dataset.insuranceFilter;state.insuranceLimit=25;return renderInsurance()}
  if(button.dataset.finishCloseout)return finishCloseout(button.dataset.finishCloseout);
  if(button.dataset.previewImage)return previewImage(button.dataset.previewImage,button.dataset.previewTitle||'Tool photo');
  if(button.dataset.viewTool)return viewTool(button.dataset.viewTool);
  if(button.dataset.moveTool)return moveTool(button.dataset.moveTool);
  if(button.dataset.editTool){closeModal('toolDetailModal');return editTool(button.dataset.editTool)}
  if(button.dataset.editJob)return editJob(button.dataset.editJob);
  if(button.dataset.jobTools)return showJobTools(button.dataset.jobTools);
  if(button.dataset.editLocation)return editLocation(button.dataset.editLocation);
  if(button.dataset.editCategory)return editCategory(button.dataset.editCategory);
  if(button.dataset.editWish)return editWish(button.dataset.editWish);
  if(button.dataset.categoryUp)return moveCategory(button.dataset.categoryUp,-1);
  if(button.dataset.categoryDown)return moveCategory(button.dataset.categoryDown,1);
  if(button.hasAttribute('data-remove-prefix')){button.closest('.prefix-row')?.remove();return}
  if(button.id==='savePrefixesBtn')return savePrefixes();
});
